// One column on a phone, more from 1024dp. The title and primary action belong to the TopAppBar.
CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchDashboardGrid(
        items = sections,
        key = { it },
        itemLabel = { it },
        modifier = Modifier.fillMaxSize(),
        span = {
            when (it) {
                in wide -> MonarchDashboardGridSpan.Full
                {{sections.pipeline}}, {{sections.performance}} -> MonarchDashboardGridSpan.Two
                else -> MonarchDashboardGridSpan.One
            }
        },
    ) { section ->
        when (section) {
            "Summary" -> Row(verticalAlignment = Alignment.CenterVertically) {
                Column(modifier = Modifier.weight(1f)) {
                    MonarchText(text = {{title}}, style = MonarchTextStyle.Heading, heading = true)
                    MonarchText(text = {{description}}, color = MonarchTheme.colors.textMuted)
                }
                MonarchButton(text = {{arrange}}, onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
            }
            "Period" -> MonarchPeriodSelector(value = period, onValueChange = { period = it }, today = {{today|millis}})
            "Key figures" -> FlowRow(
                modifier = Modifier.semantics {
                    isTraversalGroup = true
                    contentDescription = section
                },
                maxItemsInEachRow = 2,
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            ) {
                MonarchStatCard(
                    label = {{kpis.0.label}},
                    value = {{kpis.0.value|double}},
                    modifier = Modifier.weight(1f),
                    format = MonarchMetricFormat.Currency({{kpis.0.currency}}),
                    compact = true,
                )
                MonarchStatCard(label = {{kpis.1.label}}, value = {{kpis.1.value|double}}, modifier = Modifier.weight(1f))
                MonarchStatCard(
                    label = {{kpis.2.label}},
                    value = {{kpis.2.value|double}},
                    modifier = Modifier.weight(1f),
                    format = MonarchMetricFormat.Percent,
                    change = MonarchMetricChange(value = {{kpis.2.change.value|double}}, comparison = {{kpis.2.change.comparison}}),
                )
                MonarchStatCard(label = {{kpis.3.label}}, value = {{kpis.3.value|double}}, modifier = Modifier.weight(1f))
            }
            "Insights" -> MonarchInsightStrip(
                title = {{sections.insights}},
                insights = listOf(
                    MonarchInsight(
                        id = {{insight.id}},
                        title = {{insight.title}},
                        why = {{insight.why}},
                        origin = MonarchInsightOrigin.{{insight.origin|pascal}},
                        tone = {{insight.severity|tone}},
                        actionLabel = {{insight.action}},
                        onAction = {},
                    ),
                ),
            )
            {{sections.pipeline}} -> MonarchWidget(title = section) {
                MonarchFunnelChart(
                    title = {{pipeline.title}},
                    stages = listOf(
                        MonarchFunnelChartStage({{pipeline.stages.0.label}}, value = {{pipeline.stages.0.value|double}}, key = {{pipeline.stages.0.key}}),
                        MonarchFunnelChartStage({{pipeline.stages.1.label}}, value = {{pipeline.stages.1.value|double}}, key = {{pipeline.stages.1.key}}),
                        MonarchFunnelChartStage({{pipeline.stages.2.label}}, value = {{pipeline.stages.2.value|double}}, key = {{pipeline.stages.2.key}}),
                    ),
                )
            }
            {{sections.today}} -> MonarchWidget(title = section, description = {{agenda.dateLabel}}) {
                MonarchText(text = "Due today", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = {{agenda.tasks.0.title}}, modifier = Modifier.weight(1f))
                    if ({{agenda.tasks.0.overdue}}) {
                        MonarchBadge(text = "Overdue", tone = MonarchTone.Danger)
                    }
                }
                MonarchText(text = {{agenda.tasks.1.title}})
            }
            {{sections.followUps}} -> MonarchWidget(title = section) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = {{followUps.0.label}}, modifier = Modifier.weight(1f))
                    MonarchText(text = {{followUps.0.value}}, color = MonarchTheme.colors.textMuted)
                }
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = {{followUps.1.label}}, modifier = Modifier.weight(1f))
                    MonarchText(text = {{followUps.1.value}}, color = MonarchTheme.colors.textMuted)
                }
            }
            {{sections.upcoming}} -> MonarchWidget(title = section) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = {{upcoming.0.label}}, modifier = Modifier.weight(1f))
                    MonarchText(text = {{upcoming.0.value}}, color = MonarchTheme.colors.textMuted)
                }
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = {{upcoming.1.label}}, modifier = Modifier.weight(1f))
                    MonarchText(text = {{upcoming.1.value}}, color = MonarchTheme.colors.textMuted)
                }
            }
            {{sections.performance}} -> MonarchWidget(title = section) {
                MonarchBarChart(
                    title = {{performance.title}},
                    categories = listOf({{performance.data.0.month}}, {{performance.data.1.month}}, {{performance.data.2.month}}, {{performance.data.3.month}}),
                    series = listOf(
                        MonarchBarChartSeries(
                            "won",
                            {{performance.title}},
                            listOf({{performance.data.0.won|double}}, {{performance.data.1.won|double}}, {{performance.data.2.won|double}}, {{performance.data.3.won|double}}),
                        ),
                    ),
                    description = {{performance.description}},
                )
            }
            {{sections.leaders}} -> MonarchWidget(title = section) {
                MonarchLeaderboard(
                    entries = listOf(
                        MonarchLeaderboardEntry({{leaders.entries.0.name}}, value = {{leaders.entries.0.value|double}}, id = {{leaders.entries.0.id}}, secondary = {{leaders.entries.0.secondary}}),
                        MonarchLeaderboardEntry({{leaders.entries.1.name}}, value = {{leaders.entries.1.value|double}}, id = {{leaders.entries.1.id}}, secondary = {{leaders.entries.1.secondary}}),
                        MonarchLeaderboardEntry({{leaders.entries.2.name}}, value = {{leaders.entries.2.value|double}}, id = {{leaders.entries.2.id}}, secondary = {{leaders.entries.2.secondary}}),
                    ),
                    sort = MonarchBarListSort.Descending,
                    label = section,
                    valueLabel = {{leaders.valueLabel}},
                    showAvatars = false,
                )
            }
            else -> MonarchWidget(title = section) {
                MonarchActivityTimeline(
                    events = events,
                    // A lazy list inside a grid item needs a bounded height.
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 900.dp),
                    groupByDay = false,
                    density = MonarchActivityTimelineDensity.Compact,
                    now = now,
                    timeZone = {{timeZone}},
                    labels = MonarchActivityTimelineLabels(list = section, empty = "No activity yet"),
                )
            }
        }
    }
}

