val configuration = LocalConfiguration.current
val locale = remember(configuration) {
    Configuration(configuration).apply { setLocale(Locale.forLanguageTag({{locale}})) }
}
var period by remember { mutableStateOf(MonarchPeriodValue(MonarchPeriodPreset.Last7Days)) }
val now = {{now|millis}}
// The same sections as the web template and the iOS recipe, in the same order. The header parts (summary,
// period, key figures, insights) are the first full-width items, because the grid is the screen's one scrolling list.
val sections = listOf(
    "Summary", "Period", "Key figures", "Insights",
    {{sections.pipeline}}, {{sections.today}}, {{sections.followUps}}, {{sections.upcoming}}, {{sections.performance}}, {{sections.leaders}}, {{sections.activity}},
)
val wide = setOf("Summary", "Period", "Key figures", "Insights")
val events = listOf(
    MonarchActivityTimelineEvent(
        id = {{activity.0.id}},
        verb = {{activity.0.verb}},
        time = {{activity.0.time|millis}},
        actor = MonarchActivityTimelineActor({{activity.0.actor}}),
        target = {{activity.0.object}},
    ),
    MonarchActivityTimelineEvent(
        id = {{activity.1.id}},
        verb = {{activity.1.verb}},
        time = {{activity.1.time|millis}},
        actor = MonarchActivityTimelineActor({{activity.1.actor}}),
        target = {{activity.1.object}},
    ),
)

