// One column on a phone, more from 1024dp. The title and primary action belong to the TopAppBar.
CompositionLocalProvider(LocalConfiguration provides locale) {
    MonarchDashboardGrid(
        items = sections,
        key = { it },
        itemLabel = { it },
        modifier = Modifier.fillMaxSize(),
        span = {
            when (it) {
                in wide -> MonarchDashboardGridSpan.Full
                "Pipeline", "Performance" -> MonarchDashboardGridSpan.Two
                else -> MonarchDashboardGridSpan.One
            }
        },
    ) { section ->
        when (section) {
            "Summary" -> Row(verticalAlignment = Alignment.CenterVertically) {
                Column(modifier = Modifier.weight(1f)) {
                    MonarchText(text = "Home", style = MonarchTextStyle.Heading, heading = true)
                    MonarchText(text = "Sales · UK and Ireland", color = MonarchTheme.colors.textMuted)
                }
                MonarchButton(text = "Arrange", onClick = {}, variant = MonarchButtonVariant.Secondary, size = MonarchButtonSize.Sm)
            }
            "Period" -> MonarchPeriodSelector(value = period, onValueChange = { period = it }, today = 1_781_481_600_000L)
            "Key figures" -> FlowRow(
                modifier = Modifier.semantics {
                    isTraversalGroup = true
                    contentDescription = section
                },
                maxItemsInEachRow = 2,
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
            ) {
                MonarchStatCard(
                    label = "Pipeline value",
                    value = 1_200_000.0,
                    modifier = Modifier.weight(1f),
                    format = MonarchMetricFormat.Currency("GBP"),
                    compact = true,
                )
                MonarchStatCard(label = "Open deals", value = 86.0, modifier = Modifier.weight(1f))
                MonarchStatCard(
                    label = "Win rate",
                    value = 0.27,
                    modifier = Modifier.weight(1f),
                    format = MonarchMetricFormat.Percent,
                    change = MonarchMetricChange(value = 0.03, comparison = "vs last quarter"),
                )
                MonarchStatCard(label = "Closing in June", value = 14.0, modifier = Modifier.weight(1f))
            }
            "Insights" -> MonarchInsightStrip(
                title = "Insights",
                insights = listOf(
                    MonarchInsight(
                        id = "stale",
                        title = "6 deals have had no activity for 14 days",
                        why = "All six are in Proposal.",
                        origin = MonarchInsightOrigin.Rule,
                        tone = MonarchTone.Warning,
                        actionLabel = "Show deals",
                        onAction = {},
                    ),
                ),
            )
            "Pipeline" -> MonarchWidget(title = section) {
                MonarchFunnelChart(
                    title = "Deals by stage",
                    stages = listOf(
                        MonarchFunnelChartStage("Lead", value = 240.0, key = "lead"),
                        MonarchFunnelChartStage("Qualified", value = 120.0, key = "qualified"),
                        MonarchFunnelChartStage("Proposal", value = 48.0, key = "proposal"),
                    ),
                )
            }
            "Today" -> MonarchWidget(title = section, description = "Monday 15 June") {
                MonarchText(text = "Due today", style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = "Send the Harbor Labs proposal", modifier = Modifier.weight(1f))
                    if (true) {
                        MonarchBadge(text = "Overdue", tone = MonarchTone.Danger)
                    }
                }
                MonarchText(text = "Call Globex about the pilot")
            }
            "Waiting on you" -> MonarchWidget(title = section) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = "Mei Chen, Globex", modifier = Modifier.weight(1f))
                    MonarchText(text = "Replied 2 days ago", color = MonarchTheme.colors.textMuted)
                }
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = "Ana Lopez, Harbor Labs", modifier = Modifier.weight(1f))
                    MonarchText(text = "Replied yesterday", color = MonarchTheme.colors.textMuted)
                }
            }
            "Coming up" -> MonarchWidget(title = section) {
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = "Demo with Globex", modifier = Modifier.weight(1f))
                    MonarchText(text = "Tue 16 Jun, 14:00", color = MonarchTheme.colors.textMuted)
                }
                Row(
                    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3),
                    verticalAlignment = Alignment.CenterVertically,
                ) {
                    MonarchText(text = "Harbor Labs expected to close", modifier = Modifier.weight(1f))
                    MonarchText(text = "Fri 26 Jun", color = MonarchTheme.colors.textMuted)
                }
            }
            "Performance" -> MonarchWidget(title = section) {
                MonarchBarChart(
                    title = "Deals won",
                    categories = listOf("Mar", "Apr", "May", "Jun"),
                    series = listOf(
                        MonarchBarChartSeries(
                            "won",
                            "Deals won",
                            listOf(8.0, 11.0, 9.0, 13.0),
                        ),
                    ),
                    description = "By month",
                )
            }
            "Top performers" -> MonarchWidget(title = section) {
                MonarchLeaderboard(
                    entries = listOf(
                        MonarchLeaderboardEntry("Amara Okafor", value = 9.0, id = "amara", secondary = "Enterprise"),
                        MonarchLeaderboardEntry("Lucas Martin", value = 6.0, id = "lucas", secondary = "Mid-market"),
                        MonarchLeaderboardEntry("Mei Chen", value = 3.0, id = "mei", secondary = "Mid-market"),
                    ),
                    sort = MonarchBarListSort.Descending,
                    label = section,
                    valueLabel = "Deals won",
                    showAvatars = false,
                )
            }
            else -> MonarchWidget(title = section) {
                MonarchActivityTimeline(
                    events = events,
                    // A lazy list inside a grid item needs a bounded height.
                    modifier = Modifier
                        .fillMaxWidth()
                        .heightIn(max = 900.dp),
                    groupByDay = false,
                    density = MonarchActivityTimelineDensity.Compact,
                    now = now,
                    timeZone = "Europe/London",
                    labels = MonarchActivityTimelineLabels(list = section, empty = "No activity yet"),
                )
            }
        }
    }
}

